package com.bank.washtrade;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

// Finds offsetting (zero-sum) transaction triples for National Bank of India.
public class WashTradeDetector {
    private static final Logger log = Logger.getLogger(WashTradeDetector.class.getName());
    private static final BigDecimal TARGET = BigDecimal.ZERO;

    // All unique triples summing to zero. O(n^2) after an O(n log n) sort.
    public List<List<BigDecimal>> zeroSumTriples(BigDecimal[] amounts) {
        List<List<BigDecimal>> result = new ArrayList<>();
        if (amounts == null || amounts.length < 3) return result;

        BigDecimal[] a = Arrays.copyOf(amounts, amounts.length);
        Arrays.sort(a);                              // sort a COPY, keep original
        int n = a.length;

        for (int i = 0; i < n - 2; i++) {
            // Skip duplicate fixed element (point 1).
            if (i > 0 && a[i].compareTo(a[i - 1]) == 0) continue;
            // Early exit: smallest fixed element already > 0 → no zero sum.
            if (a[i].compareTo(TARGET) > 0) break;

            int left = i + 1, right = n - 1;
            while (left < right) {
                BigDecimal sum = a[i].add(a[left]).add(a[right]);
                int cmp = sum.compareTo(TARGET);
                if (cmp == 0) {
                    result.add(List.of(a[i], a[left], a[right]));
                    // Skip duplicates for left (point 2) and right (point 3).
                    BigDecimal lv = a[left], rv = a[right];
                    while (left < right && a[left].compareTo(lv) == 0) left++;
                    while (left < right && a[right].compareTo(rv) == 0) right--;
                } else if (cmp < 0) {
                    left++;      // sum too small → raise it
                } else {
                    right--;     // sum too large → lower it
                }
            }
        }
        log.info(() -> "Found " + result.size() + " zero-sum triples");
        return result;
    }
}
