package com.bank.washtrade;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: detect offsetting triples in a day's transactions.
public class WashTradeDemo {
    private static final Logger log = Logger.getLogger(WashTradeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        WashTradeDetector detector = new WashTradeDetector();

        // Rajesh (SAV2001) signed amounts (credits +, debits -), with duplicates.
        BigDecimal[] amounts = {
            bd("-1000"), bd("-1000"), bd("500"), bd("500"), bd("1000"), bd("0")
        };
        List<List<BigDecimal>> triples = detector.zeroSumTriples(amounts);
        log.info(() -> "Unique offsetting triples: " + triples);
    }
}
